        /// </summary>
        [DllImport(__DllName, EntryPoint = "mw_music_get_position", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern MwResult mw_music_get_position(ulong handle, MwMusicPosition* @out);

        /// <summary>
