        /// </summary>
        [DllImport(__DllName, EntryPoint = "mw_bgm_play", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern MwResult mw_bgm_play(ulong handle);

        /// <summary>
        ///  BGM を停止する(`mw_music_stop` の BGM 版)。`Playing` 中は既定ランプでフェード
        ///  アウトしてから位置を 0 に戻し `Ready` へ、`Paused` 中は即座に `Ready` へ
        ///  (`mw_core::MusicVoice::stop` 参照)。
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mw_bgm_stop", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern MwResult mw_bgm_stop(ulong handle);

        /// <summary>
        ///  BGM のループ区間を設定・解除する(`mw_music_set_loop` の BGM 版。初期構築仕様
        ///  『§2』M14「ループ再生」)。「BGM トラック全体をループさせたい」場合は、呼び出し側が
        ///  既に把握している総フレーム数を使って `(0, total_frames)` を渡すこと——
        ///  `mw_music_set_loop` と同様、ネイティブ側は総フレーム数を問い合わせる API を
        ///  持たない(呼び出し側が素材メタデータ等から把握している前提。同じ設計判断)。
        ///
        ///  `begin_frames == 0 &amp;&amp; end_frames == 0` はループ解除([`LOOP_CLEAR_SENTINEL`] と
        ///  同じ規約)。それ以外で `begin_frames &gt;= end_frames` は `MwResult::ErrInvalidLoopRegion`。
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mw_bgm_set_loop", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern MwResult mw_bgm_set_loop(ulong handle, ulong begin_frames, ulong end_frames);

        /// <summary>
        ///  出力レイテンシ(ns)を取得する(初期構築仕様『§5.5』`mw_get_output_latency_ns`)。
        ///
        ///  `Backend::output_latency_ns` の実測値をそのまま返す。**0 は「まだ不明」を
        ///  意味する**(オーディオコールバックが1度も走っていない。実測上 0ns ちょうどに
        ///  なることはまず無いため、この特殊値を「たまたま 0ns だった」と取り違える実害は
        ///  無い——`mw_backend::Backend::output_latency_ns` のドキュメント参照)。
        ///
        ///  あわせて、`Backend::log_output_latency_once`(1インスタンスにつき1回だけ
        ///  ログへ残す)をこのゲームスレッド経路から呼ぶ(**コールバック内から呼んでは
        ///  いけない**——`mw_log!` はアロケーションとロックを伴うため、初期構築仕様
        ///  『§5.3』のリアルタイム安全性規約に抵触する。`Instance::log_buffer_info_once`
        ///  と同じ配線パターン)。
        ///
        ///  # Safety
        ///  `out_ns` は書き込み可能な `u64` を指す有効なポインタであるか、null で
        ///  なければならない(null は書き込みを行わず `MwResult::ErrNullPointer`)。
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mw_get_output_latency_ns", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern MwResult mw_get_output_latency_ns(ulong handle, ulong* out_ns);

        /// <summary>
        ///  出力コールバックのアンダーラン(の疑い)統計を取得する(初期構築仕様『§2』M3
        ///  「アンダーラン検知・テレメトリ」)。
        ///
        ///  **`mw_poll_events` で読める `MwEventKind::Underrun` とは別物。** あちらは
        ///  楽曲/BGM のデコードリングバッファがデータ供給に追いつかず無音で埋めたことの
        ///  検知(M2)。こちらは音声コールバック自体の間隔が想定より開いたこと——OS 側の
        ///  出力バッファが実際に枯渇した(音が途切れた)ことの直接的な兆候、またはその
        ///  一歩手前の状態を示す検知(M3)。両者の関係・検知方法の詳細は
        ///  `mw_backend::underrun` モジュール doc / [`MwOutputUnderrunStats`] のドキュメント
        ///  を参照。
        ///
        ///  `out` には累計検知回数(`count`)・直近の検知時刻(`last_host_time_ns`、
        ///  `mw_host_time_ns()` と同じ時計。未検知なら 0)・直近まで連続して検知した回数
        ///  (`consecutive_count`)を書き込む。GC アロケーションゼロ。
        ///
        ///  あわせて **`se_schedule_overflow_count`**(予約 SE のキューが満杯で挿入できず
        ///  発音されなかった累計件数)も書き込む。🔴 **`mw_se_schedule` は予約が捨てられても
        ///  `Ok` を返す**ので、鳴らなかったことに気付ける口はここしか無い。
        ///  バックエンド由来の上3つと出自が違う理由は [`MwOutputUnderrunStats`] のドキュメント参照。
        ///
        ///  あわせて、新たに検知した分があれば[`Backend::log_new_output_underruns`]
        ///  (`mw_backend::Backend`)をこのゲームスレッド経路から呼ぶ(**コールバック内
        ///  から呼んではいけない**——`mw_log!` はアロケーションとロックを伴うため、初期構築
        ///  仕様『§5.3』のリアルタイム安全性規約に抵触する。`mw_get_output_latency_ns` と
        ///  同じ配線パターン)。
        ///
        ///  # Safety
        ///  `out` は書き込み可能な [`MwOutputUnderrunStats`] を指す有効なポインタである
        ///  か、null でなければならない(null は書き込みを行わず `MwResult::ErrNullPointer`)。
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mw_get_output_underrun_stats", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern MwResult mw_get_output_underrun_stats(ulong handle, MwOutputUnderrunStats* @out);

        /// <summary>
        ///  イベントをポーリングする(初期構築仕様『§4.6 イベント通知』, M2-6)。
        ///
        ///  C → C# のコールバックはしない(『§2』M4, 確定)。呼び出し側が確保した `buf`
        ///  (要素数 `cap`)へ blittable な [`MwEvent`] を直接書き込む。GC アロケーションゼロ
        ///  (初期構築仕様『§5.4』)。
        ///
        ///  **戻り値は他の FFI 関数と異なる**: 成功時は `MwResult::Ok`(常に0)固定ではなく、
        ///  **実際に書き込んだ件数**(0以上)を返す——毎フレーム呼ぶ関数として、呼び出し側が
        ///  知りたいのはまさにこの件数であり、`0` を「成功」に固定してしまうと別の出力引数で
        ///  件数を返す必要が生じ、アロケーションゼロという目的に対してかえって遠回りになる
        ///  (`buf`/`cap` 自体は元々呼び出し側所有のバッファなので、この設計でも新たな
        ///  アロケーションは発生しない)。失敗時は他の関数と同じ `MwResult` の負の値
        ///  (`as i32`)を返す——「エラーは負の整数」という初期構築仕様『§4.8』の規約自体は
        ///  破っていない(`MwResult::Ok` 以外の成功値が無いだけ)。
        ///
        ///  `out_dropped` には、キューが固定容量(【仮】64)を超えて溢れたために
        ///  **今回のポーリングで新たに判明した**破棄イベント件数を書き込む(黙って捨てない。
        ///  『§4.6』)。前回までに報告済みの分は含まない——累積は呼び出し側の責務にしない。
        ///
        ///  ## M3(案A): Android(AAudio)切断からの内部再オープン
        ///
        ///  初期構築仕様『§6』(確定)「ストリーム自体の切断(AAudio の disconnect 等)は
        ///  ミドルウェア内部で再オープンし、イベントで通知する」の入口はここ。ドレイン中に
        ///  `MwEventKind::StreamError { reason: DeviceUnavailable }` を観測すると
        ///  [`crate::handle::Instance::note_stream_error`] が内部再オープンの候補として記録し、
        ///  この関数の最後で [`handle_registry::maybe_reopen`] を呼んで(バックオフの都合が
        ///  良ければ)実際に試みる——**この関数自体が「ゲームスレッドから毎フレーム呼ばれる」
        ///  関数であることを利用しており、専用のポンプ・監視スレッドは新設していない**
        ///  (再オープンはゲームスレッド側で行う)。
        ///
        ///  🔴 **iOS/tvOS では次の呼び出しが丸ごとコンパイルから除かれる**(`cfg`)。
        ///  iOS には実機で確認済みの既存の復帰経路(`mw-backend::ios_interruption`)が別途
        ///  あり、同じ `Event::StreamError { reason: DeviceUnavailable }` に対して二重に
        ///  反応させないため——「どちらの経路を通るか」を実行時の条件分岐ではなく
        ///  コンパイル時の `cfg` 1箇所だけで確定させている
        ///  (`handle_registry::maybe_reopen` のドキュメント参照)。
        ///
        ///  この関数は「アロケーションゼロで毎フレーム呼ぶ」という上の設計方針の対象では
        ///  あるが、内部再オープンの試行自体は稀にしか起きず(切断イベントを観測した直後、
        ///  かつバックオフの間隔条件を満たしたときだけ)、その1回に限っては
        ///  `CpalBackend::open` 相当の重い処理(デバイス列挙・ストリーム構築)をこの呼び出しの
        ///  中で同期的に行う。通常フレーム(切断が起きていない大多数のフレーム)は
        ///  `ReopenPolicy::is_due` の安価なチェックのみで即座に戻るため、定常状態の
        ///  非ブロッキング性は保たれる。
        ///
        ///  # Safety
        ///  `cap &gt; 0` の場合、`buf` は `cap` 個の [`MwEvent`] を書き込み可能な有効なポインタで
        ///  なければならない。`cap &lt;= 0` の場合は `buf` が null でもよい(書き込みを行わない。
        ///  `mw_sound_load` の `len == 0` と同じ流儀)。`out_dropped` は書き込み可能な `u32` を
        ///  指す有効なポインタであるか、null でなければならない(null は書き込みを行わず
        ///  `MwResult::ErrNullPointer` を返す)。
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mw_poll_events", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int mw_poll_events(ulong handle, MwEvent* buf, int cap, uint* out_dropped);


    }

    /// <summary>
    ///  C# へポーリングで渡す1件分のイベント(blittable, `#[repr(C)]`)。
    ///
    ///  Marshal を挟まず直接読める形にするため、可変長データ・参照型は一切持たない
    ///  (初期構築仕様『§4.6』「呼び出し側が確保したバッファに blittable 構造体で書き込み、
    ///  GC アロケーションゼロ」)。
    ///
    ///  # `payload` を種別ごとに分けず1本(u64)にまとめた理由
    ///
    ///  種別ごとに付随データの意味は異なる(`Underrun` はフレーム数、`MusicLooped` は
    ///  折り返し位置、`StreamError` は理由コード)が、**いずれも 64bit 符号無し整数
    ///  1個に収まる**。選択肢として C の `union` 相当(Rust の `#[repr(C)] union` や
    ///  複数フィールドを持つ構造体)も検討したが、
    ///
    ///  - union は C# 側で `[StructLayout(LayoutKind.Explicit)]` の `FieldOffset` 越しに
    ///    読む必要があり、「Marshal を挟まず直接読める」という要件に対してかえって
    ///    C# 側の可読性を落とす(どのフィールドを読むべきかを `kind` を見て呼び出し側が
    ///    毎回判断する点は `payload` 1本でも union でも変わらない)
    ///  - 現状のどの種別も付随データは高々1個の数値で表現でき、複数フィールドを
    ///    同時に持つ種別が無い(将来増えた場合は `payload` を複数本に増やすか、
    ///    その時点で union 化を検討すればよい——ABI 破壊は semver メジャーでのみ
    ///    許可される、初期構築仕様『§4.8』)
    ///
    ///  という理由から、最も単純な「タグ + 単一の数値」で足りると判断した。
    ///
    ///  各種別での意味(`kind` ごと。`RouteChanged`/`MusicEnded`/`ClipperEngaged` は
    ///  付随データを持たないため常に 0):
    ///  - `Underrun`: このコールバック群で集約されたアンダーランフレーム数
    ///    (`mw_core::mixer::Mixer::report_underrun` のドキュメント参照。1コールバックごと
    ///    ではなく、連続するアンダーランをまとめて報告する)
    ///  - `MusicLooped`: 折り返し先(曲頭からのフレーム位置)
    ///  - `StreamError`: `mw_core::StreamErrorReason` の判別子をそのまま `u64`化したもの
    ///  - `AudioInterruptionEnded`: 復帰(ストリーム再開)を試みて成功したら 1、それ以外は 0
    ///    (`AudioInterruptionBegan` は付随データを持たないため常に 0)
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    internal unsafe partial struct MwEvent
    {
        public MwEventKind kind;
        public ulong payload;
    }

    /// <summary>
    ///  `mw_music_get_position` が書き込む音楽クロックのスナップショット
    ///  (初期構築仕様『§4.4 音楽クロック』『§5.5』)。blittable(`#[repr(C)]`)。
    ///
    ///  フィールドは `mw_core::MusicClockSnapshot` に1:1で対応する。毎フレーム呼ばれる
    ///  関数の出力型(初期構築仕様『§5.4』: GC アロケーションゼロ)なので、Marshal を
    ///  挟まず直接読める構造にしてある(`event.rs::MwEvent` と同じ設計方針。あちらの
    ///  ドキュメントコメント「payload を種別ごとに分けず1本にまとめた理由」も参照)。
    ///
    ///  ## `is_playing` を `bool` ではなく `u8` にした理由
    ///
    ///  C# の `bool` は既定のマーシャリングでは 4 バイト(Win32 `BOOL` 相当)として
    ///  扱われることがあり、Rust の `bool`(`#[repr(C)]` 構造体内でも常に 1 バイト)と
    ///  単純な `[StructLayout(LayoutKind.Sequential)]` ではレイアウトが一致しない
    ///  (フィールドごとに `[MarshalAs(UnmanagedType.U1)]` を明示すれば一致させられるが、
    ///  csbindgen の自動生成コードにその指定をさせる仕組みは無く、手で後から
    ///  付け足すのは「手書きの宣言ズレを構造的に排除する」という csbindgen 採用の目的
    ///  (`crates/mw-ffi/CLAUDE.md`)に反する)。そこで `event.rs::MwEvent` の
    ///  `payload: u64` と同じ考え方で、素の `u8`(0 または 1)として持たせ、C# 側の
    ///  bool への解釈は呼び出し側(手書きの薄いラッパ `Mw.Native`)の責務にする——
    ///  これで構造体全体が疑いなく blittable になる。
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    internal unsafe partial struct MwMusicPosition
    {
        /// <summary>
        ///  楽曲ボイスをこれまでにレンダリングしたフレーム数(= 曲位置)。
        /// </summary>
        public ulong song_frames;
        /// <summary>
        ///  上記フレーム数に対応するホスト単調時刻(ナノ秒)。`mw_host_time_ns()` と
        ///  同じ時計。
        /// </summary>
        public ulong host_time_ns;
        /// <summary>
        ///  出力サンプルレート [Hz]。0 は「まだ確定していない」。
        /// </summary>
        public uint sample_rate;
        /// <summary>
        ///  楽曲ボイスの再生状態。`u8`/`i32` ではなく [`MwMusicState`] を直接フィールド型に
        ///  している理由は [`MwMusicState`] のドキュメント参照(Rust が書き込む値は常に
        ///  妥当な判別子であり、C# が不正値を書き戻す経路が無いため enum を直接使っても
        ///  未定義動作の余地が無い。かつ csbindgen に C# `enum` を生成させる実際の
        ///  仕掛けにもなっている)。
        /// </summary>
        public MwMusicState state;
        /// <summary>
        ///  楽曲が進行中か(`0`/`1`)。上記「`bool` ではなく `u8` にした理由」参照。
        /// </summary>
        public byte is_playing;
        /// <summary>
        ///  世代カウンタ。不連続(シーク・停止・巻き戻し再開・ループ折り返し)のたびに
        ///  1 増える。C# 側は世代を跨いだ外挿・補間をしてはならない
        ///  (`mw_core::MusicClockSnapshot` のドキュメント参照)。
        /// </summary>
        public uint generation;
    }

    /// <summary>
    ///  `mw_get_output_underrun_stats` が書き込む、出力コールバックのアンダーラン
    ///  (の疑い)統計(初期構築仕様『§2』M3「アンダーラン検知・テレメトリ」)。
    ///  blittable(`#[repr(C)]`)。
    ///
    ///  **`mw_core::Event::Underrun`(`mw_poll_events` 経由)とは別物。** あちらは
    ///  楽曲/BGM のデコードリングバッファ側のアンダーラン、こちらは音声コールバック
    ///  自体の間隔異常(OS 側出力バッファの枯渇の兆候)。詳細な違いは
    ///  `mw_backend::underrun` モジュール doc / `mw_backend::Backend::output_underrun_count`
    ///  のドキュメントを参照。
    ///
    ///  先頭3フィールドは `mw_backend::Backend` の `output_underrun_count` /
    ///  `last_output_underrun_host_time_ns` / `consecutive_output_underrun_count` に
    ///  1:1で対応する。`MwMusicPosition` と同じ設計方針(Marshal を挟まず直接読める
    ///  構造体、GC アロケーションゼロ)。
    ///
    ///  🔴 **`se_schedule_overflow_count` だけは出自が違う**(`mw_core::Mixer` のカウンタで、
    ///  バックエンドとは無関係)。それでもここへ相乗りさせているのは、**この構造体が
    ///  「音声スレッド側で黙って失われたものを、ゲームスレッドが1回の呼び出しで拾う口」**
    ///  だからである —— 用途(毎フレームの診断ポーリング)も要求(GC アロケーションゼロ)も
    ///  同じで、カウンタ1本のために P/Invoke をもう1回増やすほうが割に合わない。
    ///  ⚠️ **フィールドを足すときは、この「黙って失われたもの」という基準に合うかで判断すること。**
    ///  合わないものを足し始めると、この構造体は雑多な診断値の置き場になる。
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    internal unsafe partial struct MwOutputUnderrunStats
    {
        /// <summary>
        ///  累計検知回数。
        /// </summary>
        public ulong count;
        /// <summary>
        ///  直近に検知したコールバックのホスト単調時刻(ns)。`mw_host_time_ns()` と
        ///  同じ時計。まだ1度も検知していなければ 0。
        /// </summary>
        public ulong last_host_time_ns;
        /// <summary>
        ///  直近まで連続して検知した回数。検知されなかったコールバックが1回でも
        ///  挟まると 0 に戻る。
        /// </summary>
        public uint consecutive_count;
        /// <summary>
        ///  予約 SE(`mw_se_schedule`)のキューが満杯で挿入できず、**発音されなかった**
        ///  累計件数(`mw_core::Mixer::se_schedule_overflow_count`)。
        ///
        ///  🔴 **0 以外なら、鳴るはずの音が鳴っていない。** `mw_se_schedule` 自体は
        ///  コマンドキューへ積めた時点で `Ok` を返すため、**この値を見るまで失敗は一切表に出ない。**
        ///  増え続けるなら `Config::schedule_queue_capacity` が足りていないか、
        ///  予約を出しすぎている(メトロノーム・キャリブレーションのクリック)。
        ///
        ///  ⚠️ 上3つと違い、これはバックエンド由来ではなくミキサ由来(構造体 doc 参照)。
        /// </summary>
        public ulong se_schedule_overflow_count;
    }


    /// <summary>
    ///  FFI 関数の戻り値。`Ok`(0)以外は全て負の整数のエラーコード。
    /// </summary>
    internal enum MwResult : int
    {
        /// <summary>
        ///  成功。
        /// </summary>
        Ok = 0,
        /// <summary>
        ///  出力引数として渡されたポインタが null だった。
        /// </summary>
        ErrNullPointer = -1,
        /// <summary>
        ///  ハンドルが無効(未初期化 / 既に shutdown 済み / 他インスタンスのハンドル)。
        /// </summary>
        ErrInvalidHandle = -2,
        /// <summary>
        ///  出力バックエンド(cpal ストリーム)のオープンに失敗した。
        /// </summary>
        ErrBackendOpenFailed = -3,
        /// <summary>
        ///  出力バックエンドのクローズに失敗した。
        /// </summary>
        ErrBackendCloseFailed = -4,
        /// <summary>
        ///  FFI 境界内で Rust panic を捕捉した(catch_unwind)。呼び出し元に漏らさない(§5.4)。
        /// </summary>
        ErrPanic = -5,
        /// <summary>
        ///  `mw_sound_load` の `mode` が M1 未実装(`Music`)、または未知の値だった。
        ///  楽曲モードは M2 で実装する(初期構築仕様 §5.2)。
        /// </summary>
        ErrUnsupportedSoundMode = -6,
        /// <summary>
        ///  wav のパースに失敗した(RIFF/WAVE 構造が壊れている、`fmt `/`data` チャンクが無い等)。
        /// </summary>
        ErrDecodeFailed = -7,
        /// <summary>
        ///  wav のサンプルレートが不正だった(0Hz 等、壊れたファイル)。サンプルレートの不一致
        ///  自体は M2(rubato)でロード時リサンプルするため、もはやここには当たらない
        ///  (初期構築仕様 §4.7)。
        /// </summary>
        ErrUnsupportedSampleRate = -8,
        /// <summary>
        ///  wav が 16bit PCM でない、またはチャンネル数がモノ/ステレオでない。
        /// </summary>
        ErrUnsupportedFormat = -9,
        /// <summary>
        ///  指定されたサウンド ID が存在しない(未ロード / 既に解放済み)。
        /// </summary>
        ErrInvalidSoundId = -10,
        /// <summary>
        ///  コマンドキューが満杯で発行できなかった。初期構築仕様 §4.2 の
        ///  「次のコールバックで必ず発音される」という保証は、コマンドが実際にキューへ
        ///  積まれたことが前提のため、黙って捨てずにこのエラーを返す。
        /// </summary>
        ErrCommandQueueFull = -11,
        /// <summary>
        ///  `bus` 引数が固定4本(Master/BGM/SE/Voice)のいずれにも対応しない値だった。
        /// </summary>
        ErrInvalidBus = -12,
        /// <summary>
        ///  `mw_music_set_loop` の区間が不正だった(`begin &gt;= end` で、かつループ解除
        ///  (`begin == 0 &amp;&amp; end == 0`)でもない)。`mw_core::MusicVoice::set_loop` は同じ
        ///  状況を黙ってループ無しとして扱う(音声スレッドはパニックできないため、§5.3)が、
        ///  FFI 境界(ゲームスレッド経路)では黙って捨てず明示的に拒否する
        ///  (`crates/mw-ffi/src/ffi.rs::mw_music_set_loop` 参照)。
        /// </summary>
        ErrInvalidLoopRegion = -13,
    }

    /// <summary>
    ///  イベント種別。値は csbindgen が生成する C# 側 `enum MwEventKind : int` と一致する。
    ///
    ///  `RouteChanged`(初期構築仕様『§6 テンプレートとの連携ポイント』)は iOS / tvOS で
    ///  `crates/mw-backend/src/ios_interruption.rs` が発火させる(M3。reason を問わず
    ///  ルート変化のたびに1回。詳細は `mw_core::Event::RouteChanged` のドキュメント参照)。
    ///  Android では未配線。
    /// </summary>
    internal enum MwEventKind : int
    {
        RouteChanged = 0,
        Underrun = 1,
        MusicEnded = 2,
        MusicLooped = 3,
        StreamError = 4,
        /// <summary>
        ///  開発ビルドのみ発火(`mw_core::mixer::Mixer::render` 側の判定。判別子自体は
        ///  リリースビルドでも同じ値のまま予約しておく——ビルド構成によって列挙値が
        ///  ずれると、生成される C# バインディングの意味がビルドごとに変わってしまうため)。
        /// </summary>
        ClipperEngaged = 5,
        /// <summary>
        ///  OS 主導のオーディオ割り込みが始まった(M3)。`mw_core::Event::AudioInterruptionBegan`
        ///  のドキュメント参照。iOS 実機で「バックグラウンドから復帰すると SE だけ無音になる」
        ///  問題の観測手段として追加した(`crates/mw-backend/src/ios_interruption.rs`)。
        /// </summary>
        AudioInterruptionBegan = 6,
        /// <summary>
        ///  割り込みが終わった/復帰を試みた(M3)。`payload` は
        ///  `mw_core::Event::AudioInterruptionEnded::recovered`(0 or 1)をそのまま `u64` 化。
        ///  **iOS/tvOS 専用ではない**: Android(AAudio)切断からの内部再オープンの成否
        ///  (成功、またはバックオフを使い切って断念)もこの種別を再利用して通知する
        ///  (`mw_core::Event::AudioInterruptionEnded` のドキュメント参照)。
        /// </summary>
        AudioInterruptionEnded = 7,
    }

    /// <summary>
    ///  楽曲ボイスの再生状態(初期構築仕様『§4.3 楽曲再生』『§5.5』の `mw_music_state()` の
    ///  実体)。
    ///
    ///  判別子は `mw_core::MusicState::to_u8`/`clock.rs::MusicClockPublisher` が
    ///  seqlock の内側で使う数値表現と1:1で一致させてある([`MwMusicState::from_core`])。
    ///
    ///  `mw_music_state` の `out_state` 引数自体は(`MwBus`/`MwSoundMode` と同じ理由で)
    ///  この enum を直接使わず素の `i32` として渡す——モジュール doc「enum を FFI 引数に
    ///  直接使わない理由」参照(呼び出し側が範囲外の値を書き込める余地は無い out 専用
    ///  引数とはいえ、既存の規約と揃えておく)。一方 [`MwMusicPosition::state`] は
    ///  この enum の値そのものを**フィールド型として**持つ——`event.rs::MwEvent::kind`
    ///  (`MwEventKind` を直接フィールドに持つ)と同じパターンで、Rust 側が書き込む値は
    ///  常にこの enum の妥当な判別子であり、C# 側が不正値を書き込んでそれを Rust が
    ///  読み返す経路が無いため、enum 引数を避ける理由(未定義動作)がそもそも当てはまらない。
    ///
    ///  **この構造体フィールドとしての利用が、csbindgen に C# `enum` を生成させる
    ///  実際の仕掛けでもある**: 実際に生成してみて確認した挙動として、csbindgen は
    ///  「`extern "C"` 関数シグネチャに直接現れる型」だけでなく「そこに現れる `struct` の
    ///  フィールド型」も再帰的に辿って C# 側の型を生成する(`MwEvent`/`MwEventKind` が
    ///  既にそうなっている)一方、**単に同じファイルに置いてあるだけで、どこからも
    ///  参照されない `pub enum`(`MwBus`/`MwSoundMode` がまさにこれ)は生成されない**。
    ///  そのため「C# 側に列挙を生成させたいだけ」で `mw_music_state` の引数型を
    ///  `*mut MwMusicState` に変える必要は無く(むしろそれは避けたい規約違反になる)、
    ///  [`MwMusicPosition::state`] の型として使うだけで目的を達成できる。
    /// </summary>
    internal enum MwMusicState : int
    {
        Loading = 0,
        Ready = 1,
        Playing = 2,
        Paused = 3,
    }


}
